package com.bank.topearner;

import java.util.*;
import java.util.function.BinaryOperator;
import java.util.logging.*;
import static java.util.Comparator.comparingDouble;

public class MaxByDemo {
    private static final Logger log = Logger.getLogger("TopEarner");
    static {
        ConsoleHandler h = new ConsoleHandler();
        h.setFormatter(new SimpleFormatter());
        log.setUseParentHandlers(false);
        log.addHandler(h);
    }

    public static void main(String[] args) {
        List<Employee> staff = List.of(
            new Employee("Rajesh", "IT", 1000000.0),
            new Employee("Amit", "IT", 800000.0),
            new Employee("Priya", "Sales", 250000.0),
            new Employee("Neha", "Sales", 600000.0));
        TopEarnerService service = new TopEarnerService();

        Map<String, Employee> top = service.topByDepartment(staff);
        top.forEach((dept, e) ->
            log.info(() -> dept + " → " + e.getName() + " (" + e.getSalary() + ")"));
    }
}

// ─── Would be in model/Employee.java ───
class Employee {
    private final String name;
    private final String department;
    private final double salary;
    Employee(String name, String department, double salary) {
            this.name = name;
            this.department = department
            this.salary = salary;
    }
    String getName() { return name; }
    String getDepartment() { return department; }
    double getSalary() { return salary; }
}

// ─── Would be in service/TopEarnerService.java ───
class TopEarnerService {
    Map<String, Employee> topByDepartment(List<Employee> staff) {
        return staff.stream()
            .collect(java.util.stream.Collectors.toMap(
                Employee::getDepartment,                        // key: department
                e -> e,                                          // value: whole employee
                BinaryOperator.maxBy(comparingDouble(Employee::getSalary)))); // keep higher
    }
}
